import os,numpy as np,pandas as pd
from scipy.stats import spearmanr
root='../persistent/stock_data'; assets=[f[:-4] for f in os.listdir(root) if f.endswith('.csv')]
px={}
for a in assets:
 d=pd.read_csv(f'{root}/{a}.csv',parse_dates=['date']).set_index('date').sort_index(); px[a]=d.close.replace(0,np.nan)
close=pd.DataFrame(px).sort_index(); ret=close.pct_change()
# Reversal amplified when VIX is falling (risk stabilisation); continuation when VIX rising.
v=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close'].sort_index()
v=v.reindex(close.index).ffill(); regime=np.where(v.shift(1).pct_change(5)<0,1.0,-1.0)
f=(-close.pct_change(5)*regime[:,None]).shift(1).replace([np.inf,-np.inf],np.nan)
for h in [1,3,5,10]:
 fr=close.shift(-h)/close-1; vals=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8: vals.append((dt,spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic,len(z)))
 s=pd.DataFrame(vals,columns=['date','ic','n']).set_index('date'); print(h,'dates',len(s),'avg_n',round(s.n.mean(),2),'IC',round(s.ic.mean(),6),'ICIR',round(s.ic.mean()/s.ic.std(ddof=1),6),'hit',round((s.ic>0).mean(),4))
 for w in [180,360]:
  q=s.tail(w); print(' recent',w,round(q.ic.mean(),6),round(q.ic.mean()/q.ic.std(ddof=1),6),len(q))
print('coverage',round(f.notna().sum().sum()/f.size,4),'assets',len(assets)); f.to_csv('scripts/miner_2_20281228_vix_trend_reversal_signal.csv',index_label='date')

import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in U:
    d=get_stock_daily_data(s, days=2600)
    if d is not None and len(d):
        d=d.copy(); d['date']=pd.to_datetime(d['date']); d=d.set_index('date').sort_index(); frames[s]=d['close'].astype(float)
p=pd.concat(frames,axis=1).sort_index(); r=p.pct_change()
mom=p.pct_change(20).shift(1); breadth=(mom>0).mean(axis=1); reg=(breadth-0.5)*2
sig=mom.mul(reg,axis=0).clip(-0.5,0.5)
for h in [1,3,5,10]:
    fwd=p.shift(-h)/p-1; vals=[]; nms=[]
    for dt in sig.index:
        x=sig.loc[dt]; y=fwd.loc[dt]; ok=x.notna()&y.notna()
        if ok.sum()>=8: vals.append(x[ok].corr(y[ok])); nms.append(ok.sum())
    a=np.array(vals,float); ic=np.nanmean(a); sd=np.nanstd(a,ddof=1)
    print('H',h,'dates',len(a),'avgN',round(float(np.mean(nms)),2),'IC',round(float(ic),6),'ICIR',round(float(ic/sd),6),'hit',round(float(np.mean(a>0)),4))
    if h==10:
        for window in [180,360]:
            z=a[-window:]; print('RECENT',window,'IC',round(float(np.nanmean(z)),6),'ICIR',round(float(np.nanmean(z)/np.nanstd(z,ddof=1)),6),'dates',len(z))
print('coverage',float(sig.notna().sum().sum()/(len(sig)*len(U))),'dates',len(sig),'instruments',len(U),'breadth mean',float(breadth.mean()))
out=sig.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_2_20290111_breadth_conditioned_trend_signal.csv',index=False)

import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
