END=pd.Timestamp('2030-02-20')
frames={}
for f in glob.glob('../persistent/stock_data/*.csv'):
 s=os.path.basename(f)[:-4]; d=pd.read_csv(f,parse_dates=['date']).sort_values('date'); frames[s]=d[d.date<=END].set_index('date')
# Candidate: medium-term trend acceleration. 60d return excluding the most recent 10d,
# cross-sectionally demeaned and scaled by 40d realized volatility; lag one day.
rows=[]
for s,d in frames.items():
 r=d.close.pct_change(); ret60=d.close.pct_change(60); ret10=d.close.pct_change(10); vol40=r.rolling(40).std()
 base=ret60-ret10
 rows.append(pd.DataFrame({'date':d.index,'symbol':s,'base':base,'vol':vol40,
   'fwd10':d.close.shift(-10)/d.close-1,'fwd5':d.close.shift(-5)/d.close-1,'fwd20':d.close.shift(-20)/d.close-1}))
x=pd.concat(rows,ignore_index=True).sort_values(['symbol','date'])
x['med']=x.groupby('date').base.transform('median')
x['signal']=((x.base-x.med)/x.vol).groupby(x.symbol).shift(1)
x=x.sort_values('date')
for h in [5,10,20]:
 out=[]
 for dt,g in x.groupby('date'):
  z=g[['signal',f'fwd{h}']].replace([np.inf,-np.inf],np.nan).dropna()
  if len(z)>=8: out.append((dt,spearmanr(z.signal,z[f'fwd{h}']).statistic,len(z)))
 ic=pd.DataFrame(out,columns=['date','ic','n']).set_index('date'); m=ic.ic.mean(); ir=m/ic.ic.std(ddof=1)
 print(f'H{h} dates={len(ic)} avg_n={ic.n.mean():.2f} coverage={x.signal.notna().mean():.4f} IC={m:.6f} ICIR={ir:.6f} hit={(ic.ic>0).mean():.4f}')
 for a,b in [('2020','2023'),('2024','2026-07-15'),('2026-07-16','2028-12-31'),('2029-01-01','2030-02-20')]:
