 if h==10: x[['date','symbol','signal']].dropna().to_csv('scripts/miner_2_20300221_trend_acceleration_signal.csv',index=False)
w=x.pivot(index='date',columns='symbol',values='signal'); print('turnover_proxy',((w.rank(axis=1,pct=True)-w.rank(axis=1,pct=True).shift()).abs().mean(axis=1)).mean())

