f=(-r5).mul(strength,axis=0).replace([np.inf,-np.inf],np.nan); fr=px.shift(-10)/px-1
rows=[]
for i in range(len(px)-10):
 z=pd.concat([f.iloc[i],fr.iloc[i]],axis=1).dropna()
