import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y'];cut=pd.Timestamp('2032-06-10')
p=pd.DataFrame({s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').close for s in U}).sort_index().ffill();r=p.pct_change();
# Dispersion-switch: contrarian short-term reversal during unusually high cross-asset dispersion,
# otherwise intermediate trend. Dispersion and all returns lagged one day.
disp=r.shift(1).rolling(5,min_periods=5).std(axis=1); dz=(disp-disp.rolling(120,min_periods=60).mean())/(disp.rolling(120,min_periods=60).std()+1e-12)
rev=-r.rolling(5,min_periods=5).sum().shift(1); trend=r.pct_change(20).shift(1); vol=r.shift(1).rolling(20,min_periods=15).std(); f=np.where(dz.values[:,None]>0,rev.values,trend.values)/(vol.values*np.sqrt(20)+1e-12);f=pd.DataFrame(f,index=p.index,columns=p.columns).clip(-8,8)
fr={h:p.shift(-h)/p-1 for h in [1,5,10,20]}
def ic(a,b):
 ok=a.notna()&b.notna()
 if ok.sum()<8 or a[ok].nunique()<3:return np.nan
 return spearmanr(a[ok],b[ok]).statistic
rows=[]
for i,d in enumerate(p.index[:-20]):
 if d<pd.Timestamp('2020-06-01') or p.index[i+10]>cut:continue
 q=ic(f.loc[d],fr[10].loc[d]);
 if pd.notna(q):rows.append((d,q,(f.loc[d].notna()&fr[10].loc[d].notna()).sum()))
x=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date');z=x.ic
print('dates',len(z),'start',x.index.min().date(),'end',x.index.max().date(),'avg_n',x.n.mean(),'coverage',f.loc[x.index].notna().mean().mean(),'IC',z.mean(),'ICIR',z.mean()/z.std(ddof=1),'hit',(z>0).mean(),'turnover',f.rank(pct=True).diff().abs().mean().mean())
for h in [1,5,10,20]:
 q=[ic(f.loc[d],fr[h].loc[d]) for d in x.index];print('decay',h,np.nanmean(q))
for n,q in [('365',z.tail(365)),('180',z.tail(180)),('2030',z[z.index.year==2030]),('2031',z[z.index.year==2031]),('2032',z[z.index.year==2032])]:print(n,q.mean(),q.mean()/q.std(ddof=1),len(q))
f.loc[x.index].to_csv('scripts/miner_2_20320610_dispersion_switch_signal.csv');x.to_csv('scripts/miner_2_20320610_dispersion_switch_ic.csv')

