import pandas as pd, numpy as np, glob
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 p='../persistent/stock_data/'+s+'.csv'; x=pd.read_csv(p,parse_dates=['date']).set_index('date').sort_index()
 D[s]=x.close.astype(float)
px=pd.DataFrame(D).loc[:'2033-04-13']
# common panel; lag-safe factor at t, forward return t+10/t
r5=px.pct_change(5); r20=px.pct_change(20)
# market dispersion: cross-sectional absolute deviation of 1d returns, smoothed
r1=px.pct_change(1); disp=r1.sub(r1.mean(axis=1),axis=0).abs().mean(axis=1).rolling(5).mean()
# standardize dispersion expanding-ish 60d rolling
zdisp=(disp-disp.rolling(120).mean())/disp.rolling(120).std()
# candidate: reversal strength conditional on dispersion, with winsor-ish bounded multiplier
csz=lambda x: x.sub(x.mean(axis=1),axis=0).div(x.std(axis=1).replace(0,np.nan),axis=0)
variants={
 'disp_reversal_5d': -r5*(1+0.8*np.tanh(zdisp)),
 'disp_reversal_10d': -r20*(1+0.8*np.tanh(zdisp)),
 'disp_relative_reversal': -(r5-r5.mean(axis=1).values[:,None])*(1+0.8*np.tanh(zdisp)),
 'disp_reversal_blend': -(0.7*r5+0.3*r20)*(1+0.8*np.tanh(zdisp)),
}
fr=px.shift(-10)/px-1
for name,f in variants.items():
 vals=[]; turns=[]; ns=[]
 for dt in px.index:
  a=f.loc[dt]; b=fr.loc[dt]; ok=a.notna()&b.notna(); ns.append(ok.sum())
  if ok.sum()>=8: vals.append(spearmanr(a[ok],b[ok]).statistic)
  if dt != px.index[0]:
   prev=f.shift(1).loc[dt]; oo=ok&prev.notna()
   if oo.sum()>=8: turns.append((a[oo].rank(pct=True)-prev[oo].rank(pct=True)).abs().mean())
 v=np.array(vals); print(name,'dates',len(v),'avgN',np.mean(ns),'IC',np.nanmean(v),'ICIR',np.nanmean(v)/np.nanstd(v,ddof=1),'hit',np.mean(v>0),'turn',np.nanmean(turns))
 print('decay raw',end=' ')
 for h in [1,5,10,20]:
  ff=px.shift(-h)/px-1; q=[]
  for dt in px.index:
   a=f.loc[dt]; b=ff.loc[dt]; ok=a.notna()&b.notna()
   if ok.sum()>=8:q.append(spearmanr(a[ok],b[ok]).statistic)
  print(h,round(float(np.nanmean(q)),6),end='; ')
 print()

