        x=x.copy(); x['date']=pd.to_datetime(x['date']); x=x.drop_duplicates('date').set_index('date').sort_index()
        D[s]=x['close'].astype(float)
p=pd.DataFrame(D).sort_index(); r=p.pct_change()
# 40d risk adjusted momentum, lag one completed day
mom=p/p.shift(40)-1
vol=r.rolling(20).std()*np.sqrt(252)
f=mom/vol
rows=[]
for d in f.index:
    z=f.loc[d]; fr=p.pct_change(10).shift(-10).loc[d]
    q=pd.concat([z,fr],axis=1).dropna();
    if len(q)>=8: rows.append((d,len(q),q.iloc[:,0].corr(q.iloc[:,1])))
a=pd.DataFrame(rows,columns=['date','n','ic']).set_index('date')
print('data',p.index.min(),p.index.max(),'dates',len(a),'avgN',a.n.mean(),'coverage',f.notna().sum(axis=1).mean()/15)
print('IC %.6f ICIR %.6f hit %.4f'%(a.ic.mean(),a.ic.mean()/a.ic.std(),(a.ic>0).mean()))
for k in [1,5,10,20]:
 fr=p.pct_change(k).shift(-k); rr=[]
 for d in f.index:
