import numpy as np, pandas as pd, os
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
    path='../persistent/index_data/'+s+'.csv'
    if not os.path.exists(path): continue
    x=pd.read_csv(path); x['date']=pd.to_datetime(x['date']); x=x.set_index('date').sort_index()
    D[s]=x['close'].astype(float)
print('available',list(D))
p=pd.concat(D,axis=1).sort_index().ffill(); r=np.log(p).diff(); m=r.mean(axis=1)

def factor(i):
 vals={}
 for s in D:
  rr=r[s].iloc[i-61:i]; mm=m.iloc[i-61:i]; ok=rr.notna()&mm.notna()
  if ok.sum()<45: continue
  x=rr[ok].values;y=mm[ok].values;b=np.cov(x,y,ddof=1)[0,1]/(np.var(y,ddof=1)+1e-12)
  resid=np.log(p[s].iloc[i-1]/p[s].iloc[i-21])-b*np.log(p.iloc[i-1].mean()/p.iloc[i-21].mean())
  vol=np.std(rr.iloc[-20:],ddof=1)*np.sqrt(252)
  if np.isfinite(resid) and vol>1e-8: vals[s]=resid/vol
 return vals
rows=[]
for i in range(80,len(p)-10):
 vals=factor(i)
 if len(vals)<8: continue
 z=pd.DataFrame({'f':pd.Series(vals),'fw':np.log(p.iloc[i+9]/p.iloc[i-1])}).dropna()
 if len(z)>=8: rows.append((p.index[i-1],len(z),z.f.corr(z.fw,method='spearman')))
a=pd.DataFrame(rows,columns=['date','n','ic']).dropna()
print('dates',len(a),'avgN',a.n.mean(),'coverage',a.n.sum()/(len(a)*len(D)))
print('IC10 %.6f ICIR %.6f hit %.4f'%(a.ic.mean(),a.ic.mean()/(a.ic.std(ddof=1)+1e-12)*np.sqrt(len(a)),(a.ic>0).mean()))
for h in [1,5,20]:
 q=[]
 for i in range(80,len(p)-h):
  vals=factor(i)
  if len(vals)>=8:
   z=pd.DataFrame({'f':pd.Series(vals),'fw':np.log(p.iloc[i+h-1]/p.iloc[i-1])}).dropna()
   if len(z)>=8:q.append(z.f.corr(z.fw,method='spearman'))
 print('decay',h,np.nanmean(q),len(q))
print('period',a.date.min(),a.date.max())
for n in [252,504,1008]:
 q=a.tail(n);print('recent',n,'IC',q.ic.mean(),'ICIR',q.ic.mean()/(q.ic.std(ddof=1)+1e-12)*np.sqrt(len(q)))

